import{_ as e,o,c as t,a5 as n}from"./chunks/framework.DJo0M80U.js";const b=JSON.parse('{"title":"HJ65 查找两个字符串a,b中的最长公共子串","description":"中等 通过率：32.72% 时间限制：1秒 空间限制：32M 知识点 字符串 描述 查找两个字符串a,b中的最长公共子串。若有多个，输出在较短串中最先出现的那个。 注：子串的定义：将一个字符串删去前缀和后缀（也可以不删）形成的字符串。请和“子序列”的概念分开！ 数据范围：字符串长。","frontmatter":{"title":"HJ65 查找两个字符串a,b中的最长公共子串","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：32.72% 时间限制：1秒 空间限制：32M 知识点 字符串 描述 查找两个字符串a,b中的最长公共子串。若有多个，输出在较短串中最先出现的那个。 注：子串的定义：将一个字符串删去前缀和后缀（也可以不删）形成的字符串。请和“子序列”的概念分开！ 数据范围：字符串长。","sidebarWeight":20,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/动态规划【中等】/HJ65 查找两个字符串a,b中的最长公共子串.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ65 查找两个字符串a,b中的最长公共子串.md","filePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ65 查找两个字符串a,b中的最长公共子串.md"}'),i={name:"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ65 查找两个字符串a,b中的最长公共子串.md"};function r(d,a,l,h,p,s){return o(),t("div",null,[...a[0]||(a[0]=[n('<div><h1 id="hj65-查找两个字符串a-b中的最长公共子串" tabindex="-1">HJ65 查找两个字符串a,b中的最长公共子串 <a class="header-anchor" href="#hj65-查找两个字符串a-b中的最长公共子串" aria-label="Permalink to &quot;HJ65 查找两个字符串a,b中的最长公共子串&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ65 查找两个字符串a,b中的最长公共子串”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：32.72% 时间限制：1秒 空间限制：32M 知识点==字符串== <strong>描述</strong> 查找两个字符串a,b中的最长公共子串。若有多个，输出在较短串中最先出现的那个。 注：子串的定义：将一个字符串删去前缀和后缀（也可以不删）形成的字符串。请和“子序列”的概念分开！ 数据范围：字符串长度1≤�����ℎ≤300 1≤<em>length</em>≤300 进阶：时间复杂度：�(�3) <em>O</em>(_n_3) ，空间复杂度：�(�) <em>O</em>(<em>n</em>) <strong>输入描述：</strong> 输入两个字符串 <strong>输出描述：</strong> 返回重复出现的字符 <strong>示例1</strong> 输入： abcdefghijklmnopabcsafjklmnopqrstuvw ==复制== 输出： jklmnop</p></blockquote><p>为了查找两个字符串中的最长公共子串，我们可以使用动态规划的方法。具体算法如下：</p><ol><li><p>创建一个二维数组 <code>dp</code>，其中 <code>dp[i][j]</code> 表示以 <code>a[i-1]</code> 和 <code>b[j-1]</code> 结尾的最长公共子串的长度。这里，<code>a[i-1]</code> 表示字符串 <code>a</code> 的第 <code>i</code> 个字符，<code>b[j-1]</code> 表示字符串 <code>b</code> 的第 <code>j</code> 个字符。</p></li><li><p>初始化这个二维数组的所有元素为0。</p></li><li><p>遍历两个字符串的所有字符，使用双层循环。</p></li><li><p>在每次循环中，如果找到匹配的字符对 <code>a[i] == b[j]</code>，则 <code>dp[i][j] = dp[i-1][j-1] + 1</code>，否则 <code>dp[i][j] = 0</code>。</p></li><li><p>同时记录最长公共子串的长度和位置。</p></li><li><p>根据记录的位置和长度，截取并输出最长公共子串。</p></li></ol><p>以下是对应的Python代码实现：</p><h1 id="定义一个函数-用于找到两个字符串中的最长公共子串" tabindex="-1">定义一个函数，用于找到两个字符串中的最长公共子串 <a class="header-anchor" href="#定义一个函数-用于找到两个字符串中的最长公共子串" aria-label="Permalink to &quot;定义一个函数，用于找到两个字符串中的最长公共子串&quot;">​</a></h1><p>def find_longest_common_substring(a, b):</p><h1 id="如果a比b长-交换它们-确保a是较短的字符串" tabindex="-1">如果a比b长，交换它们，确保a是较短的字符串 <a class="header-anchor" href="#如果a比b长-交换它们-确保a是较短的字符串" aria-label="Permalink to &quot;如果a比b长，交换它们，确保a是较短的字符串&quot;">​</a></h1><p>if len(a) &gt; len(b): a, b = b, a</p><h1 id="获取a和b的长度" tabindex="-1">获取a和b的长度 <a class="header-anchor" href="#获取a和b的长度" aria-label="Permalink to &quot;获取a和b的长度&quot;">​</a></h1><p>len_a, len_b = len(a), len(b)</p><h1 id="初始化动态规划表格-用于记录子串长度" tabindex="-1">初始化动态规划表格，用于记录子串长度 <a class="header-anchor" href="#初始化动态规划表格-用于记录子串长度" aria-label="Permalink to &quot;初始化动态规划表格，用于记录子串长度&quot;">​</a></h1><p>dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]</p><h1 id="初始化最长公共子串的长度和在a中的结束位置" tabindex="-1">初始化最长公共子串的长度和在a中的结束位置 <a class="header-anchor" href="#初始化最长公共子串的长度和在a中的结束位置" aria-label="Permalink to &quot;初始化最长公共子串的长度和在a中的结束位置&quot;">​</a></h1><p>max_length = 0 end_index_in_a = 0</p><h1 id="遍历字符串a和b的每个字符" tabindex="-1">遍历字符串a和b的每个字符 <a class="header-anchor" href="#遍历字符串a和b的每个字符" aria-label="Permalink to &quot;遍历字符串a和b的每个字符&quot;">​</a></h1><p>for i in range(1, len_a + 1): for j in range(1, len_b + 1):</p><h1 id="如果当前字符匹配" tabindex="-1">如果当前字符匹配 <a class="header-anchor" href="#如果当前字符匹配" aria-label="Permalink to &quot;如果当前字符匹配&quot;">​</a></h1><p>if a[i-1] == b[j-1]:</p><h1 id="更新dp表格的当前位置为左上角位置的值加1" tabindex="-1">更新dp表格的当前位置为左上角位置的值加1 <a class="header-anchor" href="#更新dp表格的当前位置为左上角位置的值加1" aria-label="Permalink to &quot;更新dp表格的当前位置为左上角位置的值加1&quot;">​</a></h1><p>dp[i][j] = dp[i-1][j-1] + 1</p><h1 id="如果当前公共子串的长度大于已知的最长长度" tabindex="-1">如果当前公共子串的长度大于已知的最长长度 <a class="header-anchor" href="#如果当前公共子串的长度大于已知的最长长度" aria-label="Permalink to &quot;如果当前公共子串的长度大于已知的最长长度&quot;">​</a></h1><p>if dp[i][j] &gt; max_length:</p><h1 id="更新最长长度和结束位置" tabindex="-1">更新最长长度和结束位置 <a class="header-anchor" href="#更新最长长度和结束位置" aria-label="Permalink to &quot;更新最长长度和结束位置&quot;">​</a></h1><p>max_length = dp[i][j] end_index_in_a = i</p><h1 id="如果当前字符不匹配-重置当前位置的值为0" tabindex="-1">如果当前字符不匹配，重置当前位置的值为0 <a class="header-anchor" href="#如果当前字符不匹配-重置当前位置的值为0" aria-label="Permalink to &quot;如果当前字符不匹配，重置当前位置的值为0&quot;">​</a></h1><p>else: dp[i][j] = 0</p><h1 id="根据最长公共子串的长度和结束位置-从a中截取并返回最长公共子串" tabindex="-1">根据最长公共子串的长度和结束位置，从a中截取并返回最长公共子串 <a class="header-anchor" href="#根据最长公共子串的长度和结束位置-从a中截取并返回最长公共子串" aria-label="Permalink to &quot;根据最长公共子串的长度和结束位置，从a中截取并返回最长公共子串&quot;">​</a></h1><p>return a[end_index_in_a - max_length:end_index_in_a]</p><h1 id="从标准输入读取两个字符串" tabindex="-1">从标准输入读取两个字符串 <a class="header-anchor" href="#从标准输入读取两个字符串" aria-label="Permalink to &quot;从标准输入读取两个字符串&quot;">​</a></h1><p>str1 = input() str2 = input()</p><h1 id="调用函数并打印输出最长公共子串" tabindex="-1">调用函数并打印输出最长公共子串 <a class="header-anchor" href="#调用函数并打印输出最长公共子串" aria-label="Permalink to &quot;调用函数并打印输出最长公共子串&quot;">​</a></h1><p>print(find_longest_common_substring(str1, str2)) 此代码将输出在较短串中最先出现的最长公共子串。例如，输入 &quot;abcdefghijklmnop&quot; 和 &quot;abcsafjklmnopqrstuvw&quot; 将会输出 &quot;jklmnop&quot;。这段代码的时间复杂度是O(n^2)，其中n是字符串的长度，空间复杂度是O(n^2)，用于存储动态规划表。如果你想要一个时间复杂度更低的算法，可以考虑使用后缀数组或者后缀树等更高级的数据结构。</p></div>',1)])])}const _=e(i,[["render",r]]);export{b as __pageData,_ as default};
